declarations.type:
∀ (model : Research.FloatingPoint.Model) (coefficients : List.{0} Real) (x : Real),
  LE.le.{0}
    (abs.{0}
      (HSub.hSub.{0, 0, 0} (Research.FloatingPoint.Horner.Q model coefficients x)
        (Research.FloatingPoint.Horner.P coefficients x)))
    (Research.FloatingPoint.Horner.E coefficients x (Research.FloatingPoint.Model.u model))

∀ {u : Real} {u_nonneg : LE.le.{0} 0 u} {round : Real → Real}
  {round_spec :
    ∀ (z : Real),
      ∃ δ, And (LE.le.{0} (abs.{0} δ) u) (Eq.{1} (round z) (HMul.hMul.{0, 0, 0} z (HAdd.hAdd.{0, 0, 0} 1 δ)))}
  {u_1 : Real} {u_nonneg_1 : LE.le.{0} 0 u_1} {round_1 : Real → Real}
  {round_spec_1 :
    ∀ (z : Real),
      ∃ δ, And (LE.le.{0} (abs.{0} δ) u_1) (Eq.{1} (round_1 z) (HMul.hMul.{0, 0, 0} z (HAdd.hAdd.{0, 0, 0} 1 δ)))},
  Eq.{1} { u := u, u_nonneg := u_nonneg, round := round, round_spec := round_spec }
      { u := u_1, u_nonneg := u_nonneg_1, round := round_1, round_spec := round_spec_1 } →
    And (Eq.{1} u u_1) (Eq.{1} round round_1)
